206	func lineageFromAdjacency(adj adjacency) map[string]*Lineage {
207		graph := make(map[string]*Lineage, len(adj))
208		for name, parents := range adj {
209			graph[name] = &Lineage{
210				Dataset: name,
211				Parents: append([]string(nil), parents...),
212			}
213		}
214		for name, parents := range adj {
